import re, random, math
from collections import Counter, defaultdict
import numpy as np

TOKEN_RE = re.compile(r"[A-Za-z0-9']+")

def clean_text(text):
    text = text.lower()
    text = re.sub(r"\s+", " ", text)
    return text.strip()

def build_corpus(paths):
    out = []
    for p in paths:
        try:
            with open(p, "r", encoding="utf-8", errors="ignore") as f:
                txt = f.read()
            out.append(clean_text(txt))
        except Exception:
            pass
    return " ".join(out)

class TinyNumPyAI:
    def __init__(self, texts, dim=32, ctx=4, seed=7):
        self.ctx = ctx
        self.dim = dim
        rng = np.random.default_rng(seed)

        all_words = []
        for t in texts:
            all_words.extend(TOKEN_RE.findall(t))
        counter = Counter(all_words)

        vocab = ["<pad>", "<unk>"] + [w for w, _ in counter.most_common(500)]
        self.word_to_id = {w: i for i, w in enumerate(vocab)}
        self.id_to_word = {i: w for w, i in self.word_to_id.items()}
        self.vocab_size = len(vocab)

        self.emb = rng.normal(0.0, 0.2, size=(self.vocab_size, self.dim)).astype(np.float32)
        self.counts = defaultdict(Counter)
        self.memory = defaultdict(float)

        for t in texts:
            words = TOKEN_RE.findall(t.lower())
            if len(words) < 2:
                continue
            for i in range(1, len(words)):
                context = tuple(words[max(0, i-self.ctx):i])
                nxt = words[i]
                self.counts[context][nxt] += 1.0
                self.memory[(context, nxt)] += 1.0

    def encode(self, text):
        words = TOKEN_RE.findall(text.lower())
        return [self.word_to_id.get(w, 1) for w in words]

    def mean_vec(self, ids):
        if not ids:
            return np.zeros(self.dim, dtype=np.float32)
        vec = self.emb[ids].mean(axis=0)
        return vec

    def predict_next(self, text):
        words = TOKEN_RE.findall(text.lower())
        if not words:
            return self.word_to_id.get("hello", 1)

        context = tuple(words[max(0, len(words)-self.ctx):])

        scores = np.zeros(self.vocab_size, dtype=np.float32)
        for wid in range(1, self.vocab_size):
            w = self.id_to_word[wid]
            # attention-like similarity to recent context
            ctx_ids = [self.word_to_id.get(x, 1) for x in context]
            if ctx_ids:
                ctx_vec = self.mean_vec(ctx_ids)
            else:
                ctx_vec = np.zeros(self.dim, dtype=np.float32)
            sim = float(np.dot(self.emb[wid], ctx_vec))

            # bigram-like memory
            bigram = self.counts.get(context, {}).get(w, 0.0)
            freq = sum(self.counts.get((context[-1],), {}).values()) if context else 0.0

            score = sim * 2.0 + bigram * 6.0 + freq * 0.01
            scores[wid] = score

        # avoid all-zero weirdness
        if np.all(scores <= 0):
            scores = np.ones(self.vocab_size, dtype=np.float32)
            scores[0] = 0.0

        probs = np.exp(scores - np.max(scores))
        probs /= probs.sum()
        return int(np.random.choice(self.vocab_size, p=probs))

    def generate(self, prompt, max_words=12):
        out = prompt.strip()
        words = TOKEN_RE.findall(out.lower())
        for _ in range(max_words):
            nxt_id = self.predict_next(out)
            nxt = self.id_to_word.get(nxt_id, "the")
            if nxt in {"<pad>", "<unk>"}:
                break
            out += " " + nxt
            words = TOKEN_RE.findall(out.lower())
            if len(words) > max_words * 2:
                break
        return out

